class TemplateParser(object):
    @staticmethod
    def parse(heat_template):
        """Given instance of HeatTemplate class parse configurations and return
        SingleTemplate instance of template env.

        :heat_template: HeatTemplate instance
        :returns: SingleTemplate instance

        """
        accepted_keys = heat_template.get_available_keys()
        env_keys = heat_template._env.keys()

        for k in env_keys:
            if k not in accepted_keys:
                del heat_template._env[k]

        return heat_template.env
